INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Jesus Christ return before 2027?', 'This market will resolve to "Yes" if The Second Coming of Jesus Christ occurs by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". The resolution source for this market will be a consensus of credible sources.', 'general', 'active', 633671.44, 31862299.79, 634171.44, 31862799.79);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the US confirm that aliens exist before 2027?', 'This market will resolve to "Yes" if the President of the United States, any member of the Cabinet of the United States, any member of the Joint Chiefs of Staff, or any US federal agency definitively states that extraterrestrial life or technology exists by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". The primary resolution source for this market will be official information from the government of the United States, however a consensus of credible reporting will a', 'politics', 'active', 828052.86, 17573121.75, 828552.86, 17573621.75);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the U.S. invade Iran before 2027?', 'This market will resolve to "Yes" if the United States commences a military offensive intended to establish control over any portion of Iran by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". For the purposes of this market, land de facto controlled by Iran or the United States as of November 4, 2025 12:00 PM ET, will be considered the sovereign territory of that country. The resolution source for this market will be a consensus of credible sources.', 'politics', 'active', 5398345.17, 23781899, 5398845.17, 23782399);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Bitcoin reach $250,000 by December 31, 2026?', 'This market will immediately resolve to "Yes" if any Binance 1 minute candle for Bitcoin (BTC/USDT) between November 24, 2025, 14:00 and December 31, 2026, 23:59 in the ET timezone has a final "High" price equal to or greater than the price specified in the title. Otherwise, this market will resolve to "No." The resolution source for this market is Binance, specifically the BTC/USDT "High" prices available at https://www.binance.com/en/trade/BTC_USDT, with the chart settings on "1m" for one-minu', 'crypto', 'active', 44340.81, 2642980.73, 44840.81, 2643480.73);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will no Fed rate cuts happen in 2026?', 'This market will resolve according to the exact amount of cuts of 25 basis points in 2026 by the Fed (including any cuts made during the December meeting). Emergency rate cuts outside of scheduled FOMC meetings will also count toward the total number of cuts in 2026. This market will remain open until December 31, 2026, 11:59 PM ET, to account for any such emergency actions. For example, if the Fed cuts rates by 50 bps after a meeting, it would be considered 2 cuts (of 25 bps each). This market ', 'world', 'active', 3088574.35, 504880.39, 3089074.35, 505380.39);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the Los Angeles Chargers win the 2027 NFL league championship?', 'This market will resolve according to the team that wins the 2027 NFL league championship. If at any point it becomes impossible for a listed team to win the 2027 NFL league championship per the rules of the NFL (e.g., they are eliminated in the playoffs), the corresponding market will resolve to “No”. If the 2027 NFL league championship game is cancelled, postponed after March 31, 2027 ET, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”. The p', 'sports', 'active', 113654.35, 2279068.86, 114154.35, 2279568.86);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Tom Steyer win the California Governor Election in 2026?', 'This market will resolve to according to the candidate who wins the 2026 California gubernatorial election currently scheduled for November 3, 2026. If the results of the election are not confirmed by July 31, 2027, this market will resolve to "Other". The resolution source for this market is the Associated Press, Fox News, and NBC. This market will resolve once all three sources call the race for the same candidate. If all three sources haven’t called the race in this state for the same candida', 'politics', 'active', 23904.74, 2366569.15, 24404.74, 2367069.15);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will China invade Taiwan by end of 2026?', 'This market will resolve to "Yes" if China commences a military offensive intended to establish control over any portion of the Republic of China (Taiwan) by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". Territory under the administration of the Republic of China including any inhabited islands will qualify, however uninhabited islands will not qualify. The resolution source for this market will be will be official confirmation by China, Taiwan, the United Nations,', 'politics', 'active', 743088.01, 19072592.25, 743588.01, 19073092.25);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the Chicago White Sox win the 2026 World Series?', 'This market will resolve according to the team that wins the 2026 MLB World Series. If at any point it becomes impossible for a listed team to win the 2026 MLB World Series per the rules of MLB (e.g., they are eliminated in the playoffs), the corresponding market will resolve to “No”. If the 2026 MLB season is cancelled, postponed after December 31, 2026 ET, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”. The primary resolution source will be ', 'sports', 'active', 30356.71, 1261418.39, 30856.71, 1261918.39);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Mojtaba Khamenei be head of state in Iran end of 2026?', 'This market will resolve to the individual who de facto holds and exercises the powers of the head of state of the Islamic Republic of Iran on December 31, 2026 at 12:00 PM ET. For the purposes of this market, “de facto holds” refers to the individual who exercises primary governing authority over the Iranian state at that time, including effective control over the armed forces, national institutions, and core executive decision-making, regardless of formal title, constitutional designation, or ', 'politics', 'active', 2406440.31, 571827.4, 2406940.31, 572327.4);